from rich.text import Text

def test_append_tokens_none():
    text = Text()
    try:
        text.append_tokens(None)
    except TypeError as e:
        print(f"Caught expected TypeError: {e}")
    else:
        print("No exception raised for append_tokens(None)")

if __name__ == "__main__":
    test_append_tokens_none()

